"""Native local-ROM frames from the v852 input acceptance calibration.

These exercise the real glyphs, cursor blink phases and dimmed selected slots.
The six emulated input trials are recorded in the calibration document; CI
replays their observation/decision boundary without a ROM or emulator.
"""
from copy import deepcopy
from pathlib import Path

import pytest

from docich.hanjuku_speedrun.hanjuku.flows import starter
from docich.hanjuku_speedrun.hanjuku.os_layer import commands
from docich.hanjuku_speedrun.hanjuku.os_layer.pixels import read_png
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import parse
from .test_hanjuku_menu_cursor_tempo import entry, state
from .test_hanjuku_visible_castle_batch import taps

FIX = Path(__file__).parent.parent / 'fixtures/hanjuku'
NAMES = ['ヴィーナス', 'アテナ', 'ミルフィーユ', 'フェデリーニ']


def native(name):
    frame = read_png(FIX / f'local-starter-{name}.png')
    return parse(frame), frame


@pytest.mark.parametrize('name,origin,target,direction', [('top', 47, NAMES[-1], 'down'),
                                                        ('bottom', 95, NAMES[0], 'up')])
def test_native_four_member_pane_proves_a_three_row_path(name, origin, target, direction):
    screen, _ = native(name)
    before = deepcopy(screen)
    assert screen.kind == 'starter_list'
    assert [row[2] for row in starter.rows(screen)] == NAMES
    assert starter.rows(screen, selected=True) == []
    reading = commands.menu_navigation_reading(screen)
    assert reading['menu'] == 'starter_upper' and reading['cursor'] == [48, origin]
    actions = commands.starter_list_batch(screen, target)
    assert actions == taps(direction, 3)
    assert entry.observation_interval_ms(state(screen), actions) == 500
    assert screen == before


def test_native_returned_cursor_precedes_a_and_the_real_lower_pane_precedes_membership():
    mem = {'chapter': 8, 'tick': 100}
    screen, frame = native('bottom')
    assert starter.step(screen, mem, frame) == taps('up', 3)
    assert mem['starter_party']['nav']['presses'] == 3
    assert mem['starter_party']['selected'] == []
    assert not mem['starter_party'].get('pending')
    screen, frame = native('top')
    actions = starter.step(screen, mem, frame)
    assert actions == [commands.pad('a')]
    assert entry.observation_interval_ms(state(screen), actions) == 1500
    assert mem['starter_party']['pending'] == 'ヴィーナス'
    assert mem['starter_party']['selected'] == []
    screen, frame = native('one-selected')
    assert starter.step(screen, mem, frame) == [commands.pad('down')]
    assert mem['starter_party']['selected'] == ['ヴィーナス']
    assert not mem['starter_party'].get('pending')
    assert not mem.get('garrison')


def test_native_dimmed_upper_origin_keeps_a_single_step_even_with_a_lower_name():
    screen, _ = native('one-selected')
    assert commands.menu_navigation_reading(screen)['cursor'] == [48, 47]
    assert starter.rows(screen, selected=True) == [(48, 119, 'ヴィーナス')]
    assert commands.starter_list_batch(screen, 'フェデリーニ') is None
    assert entry.observation_interval_ms(state(screen), [commands.pad('down')]) == 500


def test_native_final_confirmation_requires_three_names_observed_in_the_lower_pane():
    screen, frame = native('three-confirm')
    assert screen.kind == 'starter_confirm'
    assert [row[2] for row in starter.rows(screen, selected=True)] == NAMES[:3]
    mem = {'chapter': 8, 'tick': 100}
    actions = starter.step(screen, mem, frame)
    assert actions == [commands.pad('a')]
    assert mem['starter_party']['confirm_sent'] is True
    assert mem['starter_party']['selected'] == NAMES[:3]
    assert entry.observation_interval_ms(state(screen), actions) == 1500
    assert not mem.get('garrison')
